function DataProvider({ children }) {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState(null);
  useEffect(() => {
    const id = setTimeout(() => {
      setData({ name: 'Ada' });
      setLoading(false);
    }, 600);
    return () => clearTimeout(id);
  }, []);
  return children({ loading, data });
}

function App() {
  return (
    <DataProvider>
      {({ loading, data }) =>
        loading ? <p>Loading...</p> : <p>Hello, {data.name}</p>
      }
    </DataProvider>
  );
}
